#!/usr/bin/env bash
# wf diff-scoped check: changed files -> areas -> each area's lint/typecheck/test.
# An area that depends on a changed area runs its whole-area test too, so cross-area breaks show up before merge.
# FULL=1 runs the whole-area test for changed areas as well (used once per merge by /wf:ship).
# Generated by /wf:setup; edit the AREAS table, not the logic.
set -euo pipefail
BASE="${BASE:-$(git merge-base HEAD origin/main 2>/dev/null || git merge-base HEAD main)}"
FULL="${FULL:-0}"
mapfile -t CHANGED < <( { git diff --name-only "$BASE"...HEAD; git diff --name-only; git ls-files --others --exclude-standard; } | sort -u)
[ ${#CHANGED[@]} -eq 0 ] && { echo "wf check: nothing changed since $BASE"; exit 0; }

# name|dirs (space-separated, "." = repo root)|depends (area names, space-separated)|lint|typecheck|test|test-all
# Commands run from the first dir. {files} = the area's changed files, relative to that dir.
# test-all = the whole area's tests (empty: the test command without {files}).
AREAS=(
  "<name>|<dir>|<areas it depends on>|<lint cmd>|<typecheck cmd>|<test cmd {files}>|<whole-area test cmd>"
)

declare -A FILES=()
for row in "${AREAS[@]}"; do
  IFS='|' read -r name dirs _ <<<"$row"
  read -r -a dirlist <<<"$dirs"; run_in="${dirlist[0]}"; list=""
  for f in "${CHANGED[@]}"; do
    [ -e "$f" ] || continue
    for d in "${dirlist[@]}"; do
      if [ "$d" = . ] || [[ "$f" == "$d"/* ]]; then
        if [ "$run_in" = . ]; then list+=" $f"; else list+=" ${f#"$run_in"/}"; fi; break
      fi
    done
  done
  [ -n "$list" ] && FILES[$name]="${list# }"
done

run() { echo "-- $2"; (cd "$1" && eval "$2") || { echo "FAIL: $3: $2"; fail=1; }; }
fail=0; ran=0
for row in "${AREAS[@]}"; do
  IFS='|' read -r name dirs depends lint typecheck test test_all <<<"$row"
  read -r -a dirlist <<<"$dirs"; run_in="${dirlist[0]}"
  [ -n "$test_all" ] && [ "$test_all" != none ] || test_all="${test//\{files\}/}"
  if [ -n "${FILES[$name]:-}" ]; then
    echo "== $name (changed: $(wc -w <<<"${FILES[$name]}") files)"; ran=1
    for cmd in "$lint" "$typecheck"; do [ -z "$cmd" ] || [ "$cmd" = none ] || run "$run_in" "${cmd//\{files\}/${FILES[$name]}}" "$name"; done
    if [ "$FULL" = 1 ]; then cmd="$test_all"; else cmd="${test//\{files\}/${FILES[$name]}}"; fi
    [ -z "$cmd" ] || [ "$cmd" = none ] || run "$run_in" "$cmd" "$name"
  else
    hit=""; for dep in $depends; do [ -n "${FILES[$dep]:-}" ] && hit="$dep" && break; done
    [ -z "$hit" ] && continue
    echo "== $name (depends on changed area $hit)"; ran=1
    [ -z "$test_all" ] || [ "$test_all" = none ] || run "$run_in" "$test_all" "$name"
  fi
done
[ $ran -eq 0 ] && echo "wf check: no area affected by ${#CHANGED[@]} changed files"
exit $fail
